INSERT INTO `subject` VALUES (1,'国际海上避碰规则','国际海上避碰规则试题'),(2,'驾驶员考试科目一','驾驶员考试科目一试题'),(3,'驾驶员科目一真题','《机动车驾驶人科目一》真题题库（含配图 140 题，自动识别题型导入）'),(74,'ZZ自检科目306','ZZ自检科目925'),(158,'学法减分','交管12123 学法减分考试高频题库（含基础规则、道路通行、高速通行、违法记分、应急处置、驾驶证管理等）');
